(function() {

  // ── State ──
  var activeSeason = 'summer';
  var activeTypes  = [];
  var activeAges   = [];

  // ── Filter pill clicks ──
  document.getElementById('seasonPills').addEventListener('click', function(e) {
    var btn = e.target.closest('.fpill');
    if (!btn) return;
    document.querySelectorAll('#seasonPills .fpill').forEach(function(b) { b.classList.remove('active'); });
    btn.classList.add('active');
    activeSeason = btn.dataset.season;
    applyFilters();
  });

  document.getElementById('typePills').addEventListener('click', function(e) {
    var btn = e.target.closest('.fpill');
    if (!btn) return;
    btn.classList.toggle('active');
    activeTypes = Array.from(document.querySelectorAll('#typePills .fpill.active')).map(function(b) { return b.dataset.type; });
    applyFilters();
  });

  document.getElementById('agePills').addEventListener('click', function(e) {
    var btn = e.target.closest('.fpill');
    if (!btn) return;
    btn.classList.toggle('active');
    activeAges = Array.from(document.querySelectorAll('#agePills .fpill.active')).map(function(b) { return b.dataset.age; });
    applyFilters();
  });

  // ── Reset ──
  document.getElementById('btnReset').addEventListener('click', function() {
    // reset season to summer
    document.querySelectorAll('#seasonPills .fpill').forEach(function(b) { b.classList.remove('active'); });
    document.querySelector('#seasonPills .fpill[data-season="summer"]').classList.add('active');
    activeSeason = 'summer';
    // clear types and ages
    document.querySelectorAll('#typePills .fpill, #agePills .fpill').forEach(function(b) { b.classList.remove('active'); });
    activeTypes = [];
    activeAges  = [];
    // uncheck all
    document.querySelectorAll('.item__check, .subitem__check').forEach(function(cb) {
      cb.checked = false;
      var item = cb.closest('.item, .subitem');
      if (item) item.classList.remove('checked');
    });
    document.querySelectorAll('.item.expanded').forEach(function(it) { it.classList.remove('expanded'); });
    applyFilters();
  });

  // ── Apply filters ──
  function applyFilters() {
    document.querySelectorAll('.cat-card').forEach(function(card) {
      var typesRequired = card.dataset.typesRequired;
      var agesRequired  = card.dataset.agesRequired;

      // If category requires specific trip types and none selected → hide
      if (typesRequired) {
        var req = typesRequired.split(',');
        var anyType = req.some(function(t) { return activeTypes.indexOf(t) !== -1; });
        if (activeTypes.length > 0 && !anyType) { card.classList.add('hidden'); return; }
        if (activeTypes.length === 0) { card.classList.add('hidden'); return; }
      }

      // If category requires specific ages and none selected → hide
      if (agesRequired) {
        var reqA = agesRequired.split(',');
        var anyAge = reqA.some(function(a) { return activeAges.indexOf(a) !== -1; });
        if (!anyAge) { card.classList.add('hidden'); return; }
      }

      card.classList.remove('hidden');

      // Filter items inside
      var anyVisible = false;
      card.querySelectorAll('.item').forEach(function(item) {
        var visible = itemMatches(item);
        item.classList.toggle('hidden', !visible);
        if (visible) anyVisible = true;
      });

      // Hide whole card if no items visible
      if (!anyVisible) card.classList.add('hidden');

      updateCount(card);
    });

    updateProgress();
  }

  function itemMatches(item) {
    var seasons = (item.dataset.seasons || 'all').split(',');
    var types   = (item.dataset.types   || 'all').split(',');
    var ages    = (item.dataset.ages    || 'all').split(',');

    // Season check
    if (seasons.indexOf('all') === -1 && seasons.indexOf(activeSeason) === -1) return false;

    // Type check: if types specified (not 'all'), item shows only if a matching type is active
    if (types.indexOf('all') === -1) {
      if (activeTypes.length === 0) return false; // item needs specific type but none selected
      var typeMatch = types.some(function(t) { return activeTypes.indexOf(t) !== -1; });
      if (!typeMatch) return false;
    }

    // Age check: if ages specified (not 'all'), item shows only if a matching age is active
    if (ages.indexOf('all') === -1) {
      if (activeAges.length === 0) return true; // no age filter = show all-age items; hide age-specific? No: show them all
      // Actually: if no age selected, show items that are "all". If age selected, show matching.
      // Re-think: age-tagged items are extras - show them when matching age is selected.
      // If no age selected, we only show items tagged "all".
      var ageMatch = ages.some(function(a) { return activeAges.indexOf(a) !== -1; });
      if (!ageMatch) return false;
    } else {
      // item tagged "all" - always show
    }

    return true;
  }

  // ── Category toggle ──
  window.toggleCat = function(header) {
    var card = header.closest('.cat-card');
    card.classList.toggle('open');
  };

  // ── Item expand (for sub-items) ──
  window.toggleExpand = function(item) {
    item.classList.toggle('expanded');
  };

  // ── Parent checkbox → toggle all sub-items ──
  window.toggleParent = function(checkbox) {
    var item = checkbox.closest('.item');
    var checked = checkbox.checked;
    item.querySelectorAll('.subitem__check').forEach(function(sub) {
      sub.checked = checked;
      var subitem = sub.closest('.subitem');
      if (subitem) subitem.classList.toggle('checked', checked);
    });
    item.classList.toggle('checked', checked && item.querySelectorAll('.subitem__check').length === 0);
    updateAllCounts();
    updateProgress();
  };

  // ── Individual checkboxes ──
  document.addEventListener('change', function(e) {
    if (e.target.classList.contains('item__check') && !e.target.classList.contains('item__check--parent')) {
      var item = e.target.closest('.item');
      if (item) item.classList.toggle('checked', e.target.checked);
      updateAllCounts();
      updateProgress();
    }
    if (e.target.classList.contains('subitem__check')) {
      var subitem = e.target.closest('.subitem');
      if (subitem) subitem.classList.toggle('checked', e.target.checked);
      // update parent if all sub-items checked
      var parentItem = e.target.closest('.item');
      if (parentItem) {
        var allSubs = parentItem.querySelectorAll('.subitem__check');
        var allChecked = Array.from(allSubs).every(function(s) { return s.checked; });
        var parentCb = parentItem.querySelector('.item__check--parent');
        if (parentCb) parentCb.checked = allChecked;
      }
      updateAllCounts();
      updateProgress();
    }
  });

  // ── Count per category ──
  function updateCount(card) {
    var cat  = card.dataset.cat;
    var el   = document.getElementById('cnt-' + cat);
    if (!el) return;
    var visItems  = Array.from(card.querySelectorAll('.item:not(.hidden)'));
    var total = 0, done = 0;
    visItems.forEach(function(item) {
      var hasSubs = item.querySelectorAll('.subitem__check').length > 0;
      if (hasSubs) {
        var subs = item.querySelectorAll('.subitem__check');
        total += subs.length;
        subs.forEach(function(s) { if (s.checked) done++; });
      } else {
        total++;
        var cb = item.querySelector('.item__check');
        if (cb && cb.checked) done++;
      }
    });
    el.textContent = done + '/' + total;
    el.classList.toggle('all-done', total > 0 && done === total);
  }

  function updateAllCounts() {
    document.querySelectorAll('.cat-card:not(.hidden)').forEach(function(card) {
      updateCount(card);
    });
  }

  // ── Overall progress ──
  function updateProgress() {
    var total = 0, done = 0;
    document.querySelectorAll('.cat-card:not(.hidden)').forEach(function(card) {
      card.querySelectorAll('.item:not(.hidden)').forEach(function(item) {
        var subs = item.querySelectorAll('.subitem__check');
        if (subs.length > 0) {
          total += subs.length;
          subs.forEach(function(s) { if (s.checked) done++; });
        } else {
          total++;
          var cb = item.querySelector('.item__check');
          if (cb && cb.checked) done++;
        }
      });
    });
    var pct = total > 0 ? Math.round(done / total * 100) : 0;
    document.getElementById('progressFill').style.width = pct + '%';
    document.getElementById('progressLabel').textContent = done + ' מתוך ' + total + ' פריטים סומנו (' + pct + '%)';
  }

  // ── Nav hamburger + scroll ──
  var nav       = document.getElementById('nav');
  var hamburger = (document.getElementById("__legacy_hamburgerBtn") || document.createElement("button"));
  var mobileMenu = (document.getElementById("__legacy_mobileMenu") || document.createElement("div"));

  // Rotating live weather in menu
  var WEATHER_CITIES = [
    { name: 'לונדון',    lat: 51.51, lon: -0.12 },
    { name: 'בודפשט',   lat: 47.50, lon: 19.04 },
    { name: 'וינה',      lat: 48.21, lon: 16.37 },
    { name: 'ורשה',      lat: 52.23, lon: 21.01 },
    { name: 'פראג',      lat: 50.08, lon: 14.44 },
    { name: 'אתונה',     lat: 37.98, lon: 23.73 },
    { name: 'אמסטרדם',  lat: 52.37, lon:  4.90 },
    { name: 'רומא',      lat: 41.90, lon: 12.49 },
  ];
  var weatherCityIndex = Math.floor(Math.random() * WEATHER_CITIES.length);

  function fetchMenuWeather() {
    var el = (document.getElementById("__legacy_menuWeatherSnippet") || document.createElement("span"));
    if (!el) return;
    weatherCityIndex = (weatherCityIndex + 1) % WEATHER_CITIES.length;
    var city = WEATHER_CITIES[weatherCityIndex];
    el.textContent = city.name + '...';
    fetch('https://api.open-meteo.com/v1/forecast?latitude=' + city.lat + '&longitude=' + city.lon + '&current_weather=true')
      .then(function(r) { return r.json(); })
      .then(function(d) {
        var t = Math.round(d.current_weather.temperature);
        var code = d.current_weather.weathercode;
        var icon = code <= 1 ? '☀️' : code <= 3 ? '⛅' : code <= 67 ? '🌧' : '❄️';
        el.textContent = city.name + ' עכשיו ' + t + '°C ' + icon;
      })
      .catch(function() { el.textContent = 'מזג אוויר באירופה'; });
  }

  if (hamburger && mobileMenu) {
    hamburger.addEventListener('click', function() {
      var isOpen = mobileMenu.classList.toggle('open');
      hamburger.setAttribute('aria-expanded', isOpen.toString());
      hamburger.setAttribute('aria-label', isOpen ? 'סגור תפריט' : 'פתח תפריט');
      document.body.style.overflow = isOpen ? 'hidden' : '';
      if (isOpen) fetchMenuWeather();
    });
    mobileMenu.querySelectorAll('a').forEach(function(link) {
      link.addEventListener('click', function() {
        var href = link.getAttribute('href'); if (href === '#newsletter' || href === 'tips.html#newsletter') return;
        mobileMenu.classList.remove('open');
        hamburger.setAttribute('aria-expanded', 'false');
        document.body.style.overflow = '';
      });
    });
  }

  if (nav) {
    window.addEventListener('scroll', function() {
      nav.classList.toggle('scrolled', window.scrollY > 10);
    });
  }

  // ── Scroll to top ──
  var scrollBtn = document.getElementById('scroll-top-btn');
  window.addEventListener('scroll', function() {
    if (scrollBtn) scrollBtn.classList.toggle('visible', window.scrollY > 300);
  });

  // ── PDF export ──
  document.getElementById('btnPdf').addEventListener('click', function() {
    // Expand all visible categories and sub-items before printing
    var expanded = [];
    document.querySelectorAll('.cat-card:not(.hidden)').forEach(function(card) {
      if (!card.classList.contains('open')) {
        card.classList.add('open');
        expanded.push({ el: card, wasOpen: false });
      }
      card.querySelectorAll('.item--expandable:not(.hidden)').forEach(function(item) {
        if (!item.classList.contains('expanded')) {
          item.classList.add('expanded');
          expanded.push({ el: item, wasOpen: false });
        }
      });
    });
    window.print();
    // Restore state after print dialog closes
    setTimeout(function() {
      expanded.forEach(function(entry) {
        if (!entry.wasOpen) entry.el.classList.remove('open', 'expanded');
      });
    }, 500);
  });

  // ── Init ──
  applyFilters();

})();

